(() => {
  const g = window.__game; const B = g.figures.bodies;
  const names = new Map(); for (const [n, s] of Object.entries(B.p)) names.set(s, n);
  const proto = Object.getPrototypeOf(B.p.heroCollar);
  const rec = [];
  const o = proto.push;
  proto.push = function (m, color, owner, part, indoor, clip) {
    const n = names.get(this) || '?';
    if (/^hero|^folk\d+_|^collar$|^neck$|^torso/.test(n)) rec.push({ n, owner, m: Array.from(m.elements).map((v) => +v.toFixed(5)), c: Array.from(color || []).map((v) => +(+v).toFixed(3)) });
    return o.call(this, m, color, owner, part, indoor, clip);
  };
  window.__frame(1, 1 / 30);
  proto.push = o;
  const h = g.player.fig ? g.player.fig.j : null;
  const hp = g.player.pos || g.player.position;
  window.__cap = rec;
  return { n: rec.length, hero: hp ? [hp.x, hp.y, hp.z] : null };
})()
